cd /home/user/catering && cat > /tmp/smoke6.exs << 'EOF'
alias Catering.Forms

params = %{
  "reference" => "ORD-6",
  "customer" => %{"name" => "Frank", "email" => "frank@example.com"},
  "line_items" => %{
    "0" => %{"dish" => "A", "quantity" => "1", "modifiers" => %{}},
    "1" => %{"dish" => "B", "quantity" => "1", "modifiers" => %{}}
  }
}

form = Forms.new_order_form() |> Forms.change(params)
prepended = Forms.add_nested(form, "order[line_items]", prepend: true, params: %{"dish" => "Z", "quantity" => "1"})
IO.inspect(Enum.map(prepended.forms[:line_items], & &1.params["dish"]), label: "after prepend add")
IO.inspect(Enum.map(prepended.forms[:line_items], & &1.name), label: "names after prepend")
EOF
mix run /tmp/smoke6.exs 2>&1 | tail -50; rm -f /tmp/smoke6.exs
